import "timezone"
import "date"

loc = timezone.location(name: "America/Los_Angeles")
months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
today = date.truncate(t: now(), unit: 1d, location: loc)

// Day total of a *_today counter = its highest reading that local day. If the counter drops
// within 3 h after local midnight, that drop is its reset: earlier readings still carried
// yesterday's total (inverter clock behind the server, e.g. no DST) and are ignored.
dayTotal = (column, tables=<-) => tables
  |> reduce(identity: {_value: 0.0, prev: -1.0}, fn: (r, accumulator) => {
      // r._start is local midnight for every window except a partial first one at the range start
      early = r._start != v.timeRangeStart and int(v: r._time) - int(v: r._start) < 10800000000000
      restart = accumulator.prev < 0.0 or (early and r._value < accumulator.prev)
      return {_value: if restart or r._value > accumulator._value then r._value else accumulator._value, prev: r._value}
    })

from(bucket: "luxmon")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "luxmon_register" and r._field == "value" and (r.name == "pv1_energy_today" or r.name == "load_energy_today"))
  |> group(columns: ["name"])
  |> sort(columns: ["_time"])
  |> aggregateWindow(every: 1d, fn: dayTotal, createEmpty: false, timeSrc: "_start", location: loc)
  |> map(fn: (r) => {
      d = date.truncate(t: r._time, unit: 1d, location: loc)
      return {
        _time: d,
        _value: r._value,
        series: if r.name == "pv1_energy_today" then "Solar" else "Consumption",
        Day: months[date.month(t: d, location: loc) - 1] + " " + string(v: date.monthDay(t: d, location: loc)) + (if d == today then " (so far)" else ""),
      }
    })
  |> group()
  |> pivot(rowKey: ["_time", "Day"], columnKey: ["series"], valueColumn: "_value")
  |> sort(columns: ["_time"])
  |> keep(columns: ["Day", "Solar", "Consumption"])

